          <Stack gap="md" mt="sm">
            {tree.subgroups.map(group => (
              <GroupNode
                key={group.name}
                group={group}
                groupKey={group.name}
                collapsedGroups={collapsedGroups}
                onToggle={toggleGroup}
              />
            ))}
            <FileList files={tree.files} />
          </Stack>
