import { describe, it, expect } from 'vitest'
import { act, renderHook } from '@testing-library/react'
import { useDriveAssignments } from './useDriveAssignments'

const FINANCE = { id: 'f1', path: 'My Drive / Finance' }
const INVOICES = { id: 'f2', path: 'My Drive / Finance / Invoices' }

describe('useDriveAssignments', () => {
  it('starts with no assignments or overrides', () => {
    const { result } = renderHook(() => useDriveAssignments())
    expect(result.current.groupAssignments.size).toBe(0)
    expect(result.current.fileOverrides.size).toBe(0)
  })

  it('sets and clears a group assignment independently of other groups', () => {
    const { result } = renderHook(() => useDriveAssignments())
    act(() => { result.current.setGroupAssignment('invoices', FINANCE) })
    act(() => { result.current.setGroupAssignment('invoices/2026', INVOICES) })

    expect(result.current.groupAssignments.get('invoices')).toEqual(FINANCE)
    expect(result.current.groupAssignments.get('invoices/2026')).toEqual(INVOICES)

    act(() => { result.current.clearGroupAssignment('invoices') })
    expect(result.current.groupAssignments.get('invoices')).toBeUndefined()
    expect(result.current.groupAssignments.get('invoices/2026')).toEqual(INVOICES)
  })

  it('sets and clears a file override independently of other files', () => {
    const { result } = renderHook(() => useDriveAssignments())
    act(() => { result.current.setFileOverride('/root/a.pdf', FINANCE) })
    act(() => { result.current.setFileOverride('/root/b.pdf', INVOICES) })

    expect(result.current.fileOverrides.get('/root/a.pdf')).toEqual(FINANCE)
    expect(result.current.fileOverrides.get('/root/b.pdf')).toEqual(INVOICES)

    act(() => { result.current.clearFileOverride('/root/a.pdf') })
    expect(result.current.fileOverrides.get('/root/a.pdf')).toBeUndefined()
    expect(result.current.fileOverrides.get('/root/b.pdf')).toEqual(INVOICES)
  })

  it('keeps group assignments and file overrides in separate namespaces', () => {
    const { result } = renderHook(() => useDriveAssignments())
    act(() => { result.current.setGroupAssignment('shared-key', FINANCE) })
    act(() => { result.current.setFileOverride('shared-key', INVOICES) })

    expect(result.current.groupAssignments.get('shared-key')).toEqual(FINANCE)
    expect(result.current.fileOverrides.get('shared-key')).toEqual(INVOICES)
  })

  it('overwrites an existing assignment when set again', () => {
    const { result } = renderHook(() => useDriveAssignments())
    act(() => { result.current.setGroupAssignment('invoices', FINANCE) })
    act(() => { result.current.setGroupAssignment('invoices', INVOICES) })
    expect(result.current.groupAssignments.get('invoices')).toEqual(INVOICES)
  })
})

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { MantineProvider } from '@mantine/core'
import DriveFolderPickerModal from './DriveFolderPickerModal'
import { ListDriveFolder } from '../../../wailsjs/go/main/App'

vi.mock('../../../wailsjs/go/main/App', () => ({
  ListDriveFolder: vi.fn(),
}))

const ROOT_ITEMS = [
  { id: 'f1', name: 'Finance', isFolder: true, size: 0 },
  { id: 'file1', name: 'notes.txt', isFolder: false, size: 123 },
]
const FINANCE_ITEMS = [
  { id: 'f2', name: 'Invoices', isFolder: true, size: 0 },
]

function setup() {
  const onClose = vi.fn()
  const onSelect = vi.fn()
  render(
    <MantineProvider>
      <DriveFolderPickerModal opened onClose={onClose} onSelect={onSelect} />
    </MantineProvider>
  )
  return { onClose, onSelect }
}

beforeEach(() => {
  vi.mocked(ListDriveFolder).mockReset()
  vi.mocked(ListDriveFolder).mockImplementation(async (folderID: string) => {
    if (folderID === 'root') return ROOT_ITEMS as any
    if (folderID === 'f1') return FINANCE_ITEMS as any
    return []
  })
})

describe('DriveFolderPickerModal', () => {
  it('loads root-level folders and filters out files', async () => {
    setup()
    expect(await screen.findByText(/Finance/)).toBeTruthy()
    expect(screen.queryByText(/notes\.txt/)).toBeNull()
  })

  it('expands lazily and does not refetch on collapse/re-expand', async () => {
    setup()
    await screen.findByText(/Finance/)

    fireEvent.click(screen.getByRole('button', { name: 'Expand Finance' }))
    expect(await screen.findByText(/Invoices/)).toBeTruthy()
    expect(vi.mocked(ListDriveFolder)).toHaveBeenCalledWith('f1')
    expect(vi.mocked(ListDriveFolder).mock.calls.filter(c => c[0] === 'f1')).toHaveLength(1)

    fireEvent.click(screen.getByRole('button', { name: 'Collapse Finance' }))
    expect(screen.queryByText(/Invoices/)).toBeNull()

    fireEvent.click(screen.getByRole('button', { name: 'Expand Finance' }))
    expect(await screen.findByText(/Invoices/)).toBeTruthy()
    expect(vi.mocked(ListDriveFolder).mock.calls.filter(c => c[0] === 'f1')).toHaveLength(1)
  })

  it('selecting a folder enables Select, which reports id and path', async () => {
    const { onClose, onSelect } = setup()
    await screen.findByText(/Finance/)

    fireEvent.click(screen.getByRole('button', { name: '📁 Finance' }))
    const selectButton = screen.getByRole('button', { name: 'Select "Finance"' })
    fireEvent.click(selectButton)

    expect(onSelect).toHaveBeenCalledWith({ id: 'f1', path: 'My Drive / Finance' })
    expect(onClose).toHaveBeenCalled()
  })

  it('Cancel closes without selecting', async () => {
    const { onClose, onSelect } = setup()
    await screen.findByText(/Finance/)

    fireEvent.click(screen.getByRole('button', { name: 'Cancel' }))
    expect(onClose).toHaveBeenCalled()
    expect(onSelect).not.toHaveBeenCalled()
  })

  it('shows an inline error instead of crashing when a fetch fails', async () => {
    vi.mocked(ListDriveFolder).mockReset()
    vi.mocked(ListDriveFolder).mockRejectedValue(new Error('boom'))
    setup()

    expect(await screen.findByText(/boom/)).toBeTruthy()
    expect(screen.getByText(/My Drive/)).toBeTruthy()
  })
})

